   199	const test_hangul_ga: u21 = 0xAC00; // U+AC00 HANGUL SYLLABLE GA
   200	
   201	test "preedit range covers exact cell width" {
   202	    const testing = std.testing;
   203	
   204	    {
   205	        const p: Preedit = .{
   206	            .codepoints = &.{.{ .codepoint = 'a' }},
   207	        };
   208	        const range = p.range(2, 9);
   209	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.start);
   210	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.end);
   211	        try testing.expectEqual(@as(usize, 0), range.cp_offset);
   212	    }
   213	
   214	    {
   215	        const p: Preedit = .{
   216	            .codepoints = &.{.{ .codepoint = test_hangul_ga, .wide = true }},
   217	        };
   218	        const range = p.range(2, 9);
   219	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.start);
   220	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 3), range.end);
   221	        try testing.expectEqual(@as(usize, 0), range.cp_offset);
   222	    }
   223	}
   224	
   225	test "preedit range shifts left at right edge" {
   226	    const testing = std.testing;
   227	
   228	    const p: Preedit = .{
   229	        .codepoints = &.{.{ .codepoint = test_hangul_ga, .wide = true }},
   230	    };
   231	    const range = p.range(9, 9);
   232	    try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 8), range.start);
   233	    try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 9), range.end);
   234	    try testing.expectEqual(@as(usize, 0), range.cp_offset);
   235	}

