169	fn prepareContext(getProcAddress: anytype) !void {
170	    const version = try gl.glad.load(getProcAddress);
171	    const major = gl.glad.versionMajor(@intCast(version));
172	    const minor = gl.glad.versionMinor(@intCast(version));
173	    errdefer gl.glad.unload();
174	    log.info("loaded OpenGL {}.{}", .{ major, minor });
175	
176	    // Need to check version before trying to enable it
177	    if (major < MIN_VERSION_MAJOR or
178	        (major == MIN_VERSION_MAJOR and minor < MIN_VERSION_MINOR))
179	    {
180	        log.warn(
181	            "OpenGL version is too old. Ghostty requires OpenGL {d}.{d}",
182	            .{ MIN_VERSION_MAJOR, MIN_VERSION_MINOR },
183	        );
184	        return error.OpenGLOutdated;
185	    }
186	
187	    // Enable debug output for the context.
188	    try gl.enable(gl.c.GL_DEBUG_OUTPUT);
189	
190	    // Register our debug message callback with the OpenGL context.
191	    gl.glad.context.DebugMessageCallback.?(glDebugMessageCallback, null);
192	
193	    // Enable SRGB framebuffer for linear blending support.
194	    try gl.enable(gl.c.GL_FRAMEBUFFER_SRGB);
